import java.util.*; class Solution { public int findIntegers(int n) { int[] f = new int[32]; f[0] = 1; f[1] = 2; for (int i = 2; i < 32; i++) { f[i] = f[i - 1] + f[i - 2]; } String s = Integer.toBinaryString(n); int ans = 0; int prevBit = 0; int len = s.length(); for (int i = 0; i < len; i++) { int bit = s.charAt(i) - '0'; if (bit == 1) { ans += f[len - 1 - i]; if (prevBit == 1) { return ans; } } prevBit = bit; } return ans + 1; } }